def cumulative_sum(tuple_list):
    # Input validation
    if not isinstance(tuple_list, list):
        raise ValueError("Input must be a list of tuples.")
    for tup in tuple_list:
        if not isinstance(tup, tuple):
            raise ValueError("All elements of the list must be tuples.")
        if not all(isinstance(item, int) for item in tup):
            raise ValueError("All elements of the tuples must be integers.")

    # Calculate the cumulative sum
    total_sum = 0
    for tup in tuple_list:
        total_sum += sum(tup)

    return total_sum

# Example test case
assert cumulative_sum([(1, 3), (5, 6, 7), (2, 6)]) == 30
assert cumulative_sum([]) == 0
assert cumulative_sum([(1, 2, 3), (), (4,), (5, 6)]) == 21
